          return (
            <div key={ses.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "10px 0", borderBottom: `1px solid ${C.border}` }}>
              <Avatar name={`${pac?.nombre} ${pac?.apellido}`} size={36} />
