            <button style={{ padding: "10px 20px", borderRadius: 10, background: "rgba(16,185,129,0.12)", border: "1px solid rgba(16,185,129,0.35)", color: C.success, fontSize: 13, fontWeight: 700, cursor: "pointer" }}>💾 Guardar Historia</button>
