// ── PLUGIN: Patient Detail ─────────────────────────────────
function EstudiosClinicos({ patient, C }) {
  const TIPOS = [
    { id: "valoracion_externa", l: "🩺 Valoración médico externo" },
    { id: "rayos_x", l: "🩻 Rayos X" },
    { id: "resonancia", l: "🧲 Resonancia (RMN)" },
  ];
  const [estudios, setEstudios] = useState([]);
  const [cargado, setCargado] = useState(false);
  const [tipo, setTipo] = useState("valoracion_externa");
  const [fecha, setFecha] = useState(new Date().toISOString().slice(0, 10));
  const [centro, setCentro] = useState("");
  const [hallazgos, setHallazgos] = useState("");
  const [enlace, setEnlace] = useState("");
  const [guardando, setGuardando] = useState(false);

  useEffect(() => {
    let vivo = true;
    if (patient && patient.id) {
      CoreServices.query("clinical_records", { paciente_id: patient.id }).then(({ data }) => {
        if (!vivo) return;
        const arr = (data && data[0] && data[0].datos && Array.isArray(data[0].datos.estudios)) ? data[0].datos.estudios : [];
        setEstudios(arr); setCargado(true);
      });
    } else { setCargado(true); }
    return () => { vivo = false; };
  }, [patient && patient.id]);

  async function persistir(nuevos) {
    const prev = await CoreServices.query("clinical_records", { paciente_id: patient.id });
    const base = (prev.data && prev.data[0] && prev.data[0].datos) ? prev.data[0].datos : {};
    const merged = { ...base, estudios: nuevos };
    await fetch(SUPABASE_URL + "/rest/v1/clinical_records?on_conflict=paciente_id", { method: "POST", headers: { "Content-Type": "application/json", "apikey": SUPABASE_KEY, "Authorization": "Bearer " + (CoreServices.getToken() || SUPABASE_KEY), "Prefer": "resolution=merge-duplicates" }, body: JSON.stringify([{ paciente_id: patient.id, datos: merged, updated_at: new Date().toISOString() }]) });
  }

  async function agregar() {
    if (!patient || !patient.id) { alert("Abre Estudios desde un paciente."); return; }
    if (!hallazgos && !enlace) { alert("Escribe los hallazgos o pega un enlace."); return; }
    setGuardando(true);
    const nuevo = { tipo, fecha, centro, hallazgos, enlace, creado: new Date().toISOString() };
    const nuevos = [nuevo, ...estudios];
    try { await persistir(nuevos); setEstudios(nuevos); setCentro(""); setHallazgos(""); setEnlace(""); }
    catch (e) { alert("No se pudo guardar: " + (e.message || e)); }
    finally { setGuardando(false); }
  }

  async function borrar(idx) {
    const nuevos = estudios.filter((_, i) => i !== idx);
    try { await persistir(nuevos); setEstudios(nuevos); } catch (e) { alert("No se pudo borrar: " + (e.message || e)); }
  }

  const inp = { width: "100%", background: "rgba(255,255,255,0.05)", border: "1px solid " + C.border, borderRadius: 8, color: C.text, fontSize: 14, padding: "8px 10px", fontFamily: "inherit", boxSizing: "border-box" };
  const lTipo = (t) => (TIPOS.find(x => x.id === t) || {}).l || t;

  return (
    <div style={{ maxWidth: 760 }}>
      <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, letterSpacing: 2, marginBottom: 12 }}>ESTUDIOS Y VALORACIONES EXTERNAS</div>
      <div style={{ background: C.surface, border: "1px solid " + C.border, borderRadius: 12, padding: 16, marginBottom: 18 }}>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 12 }}>
          <div><div style={{ fontSize: 11, color: C.muted, marginBottom: 4 }}>Tipo</div>
            <select value={tipo} onChange={e => setTipo(e.target.value)} style={inp}>{TIPOS.map(t => <option key={t.id} value={t.id}>{t.l}</option>)}</select></div>
          <div><div style={{ fontSize: 11, color: C.muted, marginBottom: 4 }}>Fecha</div>
            <input type="date" value={fecha} onChange={e => setFecha(e.target.value)} style={inp} /></div>
        </div>
        <div style={{ marginBottom: 12 }}><div style={{ fontSize: 11, color: C.muted, marginBottom: 4 }}>Médico / Centro</div>
          <input value={centro} onChange={e => setCentro(e.target.value)} placeholder="Dr. / Clínica que lo realizó" style={inp} /></div>
        <div style={{ marginBottom: 12 }}><div style={{ fontSize: 11, color: C.muted, marginBottom: 4 }}>Hallazgos / Informe</div>
          <textarea value={hallazgos} onChange={e => setHallazgos(e.target.value)} rows={3} placeholder="Resumen de los hallazgos del estudio o valoración" style={{ ...inp, resize: "vertical" }} /></div>
        <div style={{ marginBottom: 12 }}><div style={{ fontSize: 11, color: C.muted, marginBottom: 4 }}>Enlace al archivo (PDF / imagen)</div>
          <input value={enlace} onChange={e => setEnlace(e.target.value)} placeholder="Pega aquí el enlace (Drive, etc.)" style={inp} /></div>
        <Btn onClick={agregar} disabled={guardando} color={C.success}>{guardando ? "Guardando..." : "➕ Agregar a la historia"}</Btn>
      </div>
      {!cargado ? <div style={{ fontSize: 13, color: C.muted }}>Cargando…</div>
        : estudios.length === 0 ? <div style={{ fontSize: 13, color: C.muted }}>Sin estudios registrados todavía.</div>
          : estudios.map((es, i) => (
            <div key={i} style={{ background: C.surface, border: "1px solid " + C.border, borderRadius: 12, padding: 14, marginBottom: 10 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                <span style={{ fontSize: 13, fontWeight: 700, color: C.text }}>{lTipo(es.tipo)}</span>
                <span style={{ fontSize: 11, color: C.muted }}>{es.fecha}</span>
              </div>
              {es.centro && <div style={{ fontSize: 12, color: C.muted, marginBottom: 4 }}>{es.centro}</div>}
              {es.hallazgos && <div style={{ fontSize: 13, color: C.text, whiteSpace: "pre-wrap", marginBottom: 6 }}>{es.hallazgos}</div>}
              {es.enlace && <a href={es.enlace} target="_blank" rel="noreferrer" style={{ fontSize: 13, fontWeight: 700, color: C.primary, textDecoration: "none" }}>📎 Ver archivo</a>}
              <div style={{ marginTop: 8 }}><button onClick={() => borrar(i)} style={{ background: "transparent", border: "1px solid " + C.border, color: C.muted, borderRadius: 8, padding: "4px 10px", fontSize: 11, cursor: "pointer" }}>🗑️ Quitar</button></div>
            </div>
          ))}
    </div>
  );
}

function PatientDetailPlugin({ patient, sessions, onAddSession, navigate, plugins }) {
  const { C } = useApp();
  const [tab, setTab] = useState("sesiones"); const [verBienvenida, setVerBienvenida] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [showAcceso, setShowAcceso] = useState(false); const [accesoUrl, setAccesoUrl] = useState(""); const [generando, setGenerando] = useState(false);
  const [showReportes, setShowReportes] = useState(false); const [reportesPac, setReportesPac] = useState([]); const [subiendoRep, setSubiendoRep] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({ protocolo: "HILT", eva_pre: 5, eva_post: 3, notas: "", duracion_minutos: 30, subjetivo: "", objetivo: "", analisis: "", plan: "" }); const [showEdit, setShowEdit] = useState(false); const [savingEdit, setSavingEdit] = useState(false); const [showCaso, setShowCaso] = useState(false); const [savingCaso, setSavingCaso] = useState(false); const [casoForm, setCasoForm] = useState(patient.caso || {}); const [editForm, setEditForm] = useState({ nombre: patient.nombre || "", apellido: patient.apellido || "", edad: patient.edad || "", sexo: patient.sexo || "", telefono: patient.telefono || "", email: patient.email || "", condicion_principal: patient.condicion_principal || "", deporte: patient.deporte || "", nivel_actividad: patient.nivel_actividad || "Moderado", pais: patient.pais || "" });
  const patSess = sessions.filter(s => s.paciente_id === patient.id).sort((a, b) => new Date(b.fecha || 0) - new Date(a.fecha || 0));
  const mej = patSess.filter(s => s.eva_pre && s.eva_post).length ? Math.round(patSess.filter(s => s.eva_pre && s.eva_post).reduce((a, s) => a + ((s.eva_pre - s.eva_post) / s.eva_pre * 100), 0) / patSess.filter(s => s.eva_pre && s.eva_post).length) : 0;

  async function save() { setSaving(true); await onAddSession({ protocolo: form.protocolo, eva_pre: form.eva_pre, eva_post: form.eva_post, duracion_minutos: form.duracion_minutos, notas: "S: " + (form.subjetivo || "") + "\nO: " + (form.objetivo || "") + "\nA: " + (form.analisis || "") + "\nP: " + (form.plan || ""), paciente_id: patient.id, numero_sesion: patSess.length + 1 }); setShowModal(false); setSaving(false); } function abrirEdicion() { setEditForm({ nombre: patient.nombre || "", apellido: patient.apellido || "", edad: patient.edad || "", sexo: patient.sexo || "", telefono: patient.telefono || "", email: patient.email || "", condicion_principal: patient.condicion_principal || "", deporte: patient.deporte || "", nivel_actividad: patient.nivel_actividad || "Moderado", pais: patient.pais || "" }); setShowEdit(true); } async function guardarEdit() { setSavingEdit(true); const { error } = await CoreServices.update("patients", patient.id, editForm); setSavingEdit(false); if (error) { alert("No se pudo guardar: " + (error.message || "error")); return; } Object.assign(patient, editForm); setShowEdit(false); } function abrirCaso() { setCasoForm(patient.caso || {}); setShowCaso(true); } async function guardarCaso() { setSavingCaso(true); const { error } = await CoreServices.update("patients", patient.id, { caso: casoForm }); setSavingCaso(false); if (error) { alert("No se pudo guardar: " + (error.message || "error")); return; } patient.caso = casoForm; setShowCaso(false); }
  async function abrirAcceso() {
    let token = patient.portal_token;
    if (!token) {
      setGenerando(true);
      token = (crypto.randomUUID() + crypto.randomUUID()).replace(/-/g, "");
      const { error } = await CoreServices.update("patients", patient.id, { portal_token: token });
      setGenerando(false);
      if (error) { alert("No se pudo generar el acceso: " + (error.message || "error")); return; }
      patient.portal_token = token;
    }
    setAccesoUrl(`${window.location.origin}/p/${token}`);
    setShowAcceso(true);
  }
  async function abrirReportes() {
    setShowReportes(true);
    const { data } = await CoreServices.query("reportes", { paciente_id: patient.id });
    setReportesPac((data || []).sort((a, b) => new Date(b.fecha || b.created_at || 0) - new Date(a.fecha || a.created_at || 0)));
  }
  async function subirReporte(e) {
    const file = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!file) return;
    if (file.type !== "application/pdf") { alert("Por ahora solo se pueden subir archivos PDF."); return; }
    setSubiendoRep(true);
    const path = `${patient.id}/${Date.now()}_${file.name.replace(/[^a-zA-Z0-9._-]/g, "_")}`;
    const up = await CoreServices.subirArchivo("reportes", path, file);
    if (!up.ok) { setSubiendoRep(false); alert("No se pudo subir el archivo: " + up.error); return; }
    const url = await CoreServices.firmarUrl("reportes", path);
    const hoy = new Date().toISOString().slice(0, 10);
    const { data, error } = await CoreServices.insert("reportes", { paciente_id: patient.id, tipo: "pdf", titulo: file.name.replace(/\.pdf$/i, ""), storage_path: path, download_url: url, fecha: hoy, visible_paciente: true });
    setSubiendoRep(false);
    if (error) { alert("Se subió el archivo pero no se guardó el reporte: " + (error.message || "error")); return; }
    const nuevo = (data && data[0]) || { id: Date.now().toString(), titulo: file.name.replace(/\.pdf$/i, ""), fecha: hoy, download_url: url };
    setReportesPac(prev => [nuevo, ...prev]);
  }
  async function eliminarReporte(r) {
    if (!window.confirm(`¿Eliminar el reporte "${r.titulo || ""}"? Esto no se puede deshacer.`)) return;
    setReportesPac(prev => prev.filter(x => x.id !== r.id));
    if (r.storage_path) await CoreServices.borrarArchivo("reportes", r.storage_path);
    if (r.id) await CoreServices.del("reportes", r.id);
  }

  const patientPlugins = plugins.filter(p => p.patientAction);

  return (
    <div>
      <button onClick={() => navigate("patients")} style={{ background: "none", border: "none", color: C.muted, cursor: "pointer", fontSize: 13, marginBottom: 20, padding: 0 }}>← Pacientes</button>
      <Card style={{ display: "flex", alignItems: "flex-start", gap: 20, marginBottom: 20 }}>
        <Avatar name={`${patient.nombre} ${patient.apellido}`} size={64} />
        <div style={{ flex: 1 }}>
          <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: C.text }}>{patient.nombre} {patient.apellido}</h2>
          <div style={{ color: C.muted, fontSize: 13, marginTop: 4 }}>{patient.edad} años · {patient.email}</div>
          <div style={{ marginTop: 10, display: "flex", gap: 8, flexWrap: "wrap" }}>
            <Badge color={C.primary}>{patient.condicion_principal}</Badge>
            <Badge color={C.success}>{patSess.length} sesiones</Badge>
            <Badge color={C.warning}>Mejoría {mej}%</Badge>
          </div>
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", justifyContent: "flex-end" }}>
          {patientPlugins.map(plugin => (
            <button key={plugin.id} onClick={() => plugin.onPatientAction(patient, navigate)} style={{ background: dim(plugin.color), border: `1px solid ${plugin.color}30`, color: plugin.color, borderRadius: 10, padding: "8px 14px", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>
              {plugin.icon} {plugin.patientActionLabel || plugin.name}
            </button>
          ))}
          <button onClick={async () => { const datos = { paciente: { nombre: patient.nombre, apellido: patient.apellido, edad: patient.edad, sexo: patient.sexo, condicion: patient.condicion_principal, deporte: patient.deporte, email: patient.email }, exportado: new Date().toISOString(), sesiones: patSess.map(s => ({ protocolo: s.protocolo, fecha: s.fecha, numero_sesion: s.numero_sesion, eva_pre: s.eva_pre, eva_post: s.eva_post, notas: s.notas, foto: s.foto || "" })) }; const texto = JSON.stringify(datos, null, 2); const nombreArchivo = "paciente_" + (patient.apellido || "") + "_" + (patient.nombre || "paciente") + ".json"; try { if (window.showSaveFilePicker) { const h = await window.showSaveFilePicker({ suggestedName: nombreArchivo }); const w = await h.createWritable(); await w.write(texto); await w.close(); alert("Listo: guardado en la carpeta que elegiste"); } else { const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([texto], { type: "application/json" })); a.download = nombreArchivo; a.click(); } } catch (e) { if (e.name !== "AbortError") alert("No se guardo: " + (e.message || e)); } }} style={{ background: "rgba(56,189,248,0.15)", border: "1px solid rgba(56,189,248,0.4)", color: "#38BDF8", borderRadius: 10, padding: "8px 14px", fontSize: 12, fontWeight: 800, cursor: "pointer" }}>📥 Descargar para Adri</button><Btn onClick={abrirEdicion} color={C.warning}>✏️ Editar ficha</Btn><Btn onClick={abrirCaso} color={C.danger}>🚗 Caso / Accidente</Btn><Btn onClick={abrirAcceso} color={C.teal}>{generando ? "Generando..." : "🔗 Dar acceso al portal"}</Btn><Btn onClick={abrirReportes} color={C.purple}>📄 Reportes</Btn><Btn onClick={() => setShowModal(true)} color={C.primary}>+ Sesión</Btn>
        </div>
      </Card>

      <Modal open={showAcceso} onClose={() => setShowAcceso(false)} title="Acceso al portal del paciente" width={460}>
        <div style={{ textAlign: "center", padding: "4px 4px 8px" }}>
          <div style={{ fontSize: 13, color: C.muted, lineHeight: 1.6, marginBottom: 16 }}>
            {patient.nombre} puede entrar a su portal escaneando este código con la cámara del celular, o abriendo el enlace. Solo verá su propia información.
          </div>
          <div style={{ background: "#fff", display: "inline-block", padding: 14, borderRadius: 14, marginBottom: 16 }}>
            {accesoUrl ? <QRCodeSVG value={accesoUrl} size={184} /> : null}
          </div>
          <input readOnly value={accesoUrl} onFocus={e => e.target.select()} style={{ width: "100%", boxSizing: "border-box", padding: "9px 12px", borderRadius: 9, border: `1px solid ${C.border}`, background: C.surface, color: C.text, fontSize: 11, marginBottom: 14 }} />
          <div style={{ display: "flex", gap: 8 }}>
            <Btn color={C.primary} style={{ flex: 1 }} onClick={() => { try { navigator.clipboard.writeText(accesoUrl); alert("Enlace copiado"); } catch { alert("Copia manual el enlace de arriba"); } }}>📋 Copiar</Btn>
            <Btn color={C.success} style={{ flex: 1 }} onClick={() => window.open(`https://wa.me/?text=${encodeURIComponent("Hola " + (patient.nombre || "") + ", este es tu acceso a tu portal de Awake4Wellness: " + accesoUrl)}`, "_blank")}>📱 WhatsApp</Btn>
            <Btn color={C.warning} style={{ flex: 1 }} onClick={() => window.open(`mailto:${patient.email || ""}?subject=${encodeURIComponent("Tu portal Awake4Wellness")}&body=${encodeURIComponent("Hola " + (patient.nombre || "") + ", este es tu acceso a tu portal del paciente: " + accesoUrl)}`)}>✉️ Correo</Btn>
          </div>
        </div>
      </Modal>

      <Modal open={showReportes} onClose={() => setShowReportes(false)} title={`Reportes de ${patient.nombre || "paciente"}`} width={520}>
        <div style={{ padding: "2px 2px 6px" }}>
          <label style={{ display: "block", marginBottom: 16 }}>
            <input type="file" accept="application/pdf" onChange={subirReporte} style={{ display: "none" }} />
            <span style={{ display: "inline-flex", alignItems: "center", gap: 8, background: dim(C.teal), border: `1px solid ${C.teal}40`, color: C.teal, borderRadius: 10, padding: "10px 16px", fontSize: 13, fontWeight: 800, cursor: "pointer" }}>{subiendoRep ? "⏳ Subiendo..." : "📎 Subir un PDF"}</span>
          </label>
          {reportesPac.length === 0 ? (
            <div style={{ fontSize: 13, color: C.muted, padding: "8px 0", lineHeight: 1.6 }}>Aún no hay reportes. Subí el primero con el botón de arriba.</div>
          ) : reportesPac.map((r, i) => (
            <div key={r.id || i} style={{ padding: "12px 0", borderBottom: i < reportesPac.length - 1 ? `1px solid ${C.border}` : "none" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                <div><div style={{ fontSize: 13, fontWeight: 700 }}>📄 {r.titulo || "Reporte"}</div><div style={{ fontSize: 11, color: C.muted }}>{r.fecha ? new Date(r.fecha).toLocaleDateString("es-ES") : ""}</div></div>
                <div style={{ display: "flex", gap: 6 }}>
                  {r.download_url && <button onClick={() => window.open(r.download_url, "_blank")} style={{ background: "none", border: `1px solid ${C.border}`, color: C.text, borderRadius: 8, padding: "5px 10px", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>Abrir</button>}
                  <button onClick={() => eliminarReporte(r)} title="Eliminar reporte" style={{ background: "none", border: `1px solid ${C.danger}40`, color: C.danger, borderRadius: 8, padding: "5px 10px", fontSize: 11, fontWeight: 700, cursor: "pointer" }}>🗑️ Eliminar</button>
                </div>
              </div>
              {r.download_url ? (
                <div style={{ display: "flex", gap: 6 }}>
                  <Btn color={C.primary} style={{ flex: 1, padding: "6px", fontSize: 11 }} onClick={() => { try { navigator.clipboard.writeText(r.download_url); alert("Link del reporte copiado"); } catch { alert("Copia el link manualmente"); } }}>📋 Copiar link</Btn>
