                      <td style={{ padding: "5px 10px", color: C.text }}>{c[3]}</td>
                      <td style={{ padding: "5px 10px", fontWeight: 700, color: est === "Fuera" ? C.danger : est === "Dentro" ? C.success : C.muted }}>{est}</td>
                    </tr>
