          <div style={{ marginTop: 20, display: "flex", justifyContent: "flex-end" }}><Btn color={C.success}>✓ Guardar</Btn></div>
        </Card>
      )}

      <Modal open={showCaso} onClose={() => setShowCaso(false)} title="Caso / Accidente (PIP)" width={620}><div onClick={() => setCasoForm(p => ({ ...p, es_accidente: !p.es_accidente }))} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 14px", borderRadius: 10, cursor: "pointer", marginBottom: 16, background: casoForm.es_accidente ? "rgba(239,68,68,0.1)" : "rgba(255,255,255,0.03)", border: `1px solid ${casoForm.es_accidente ? C.danger : C.border}` }}><span style={{ fontSize: 14, fontWeight: 700, color: casoForm.es_accidente ? C.danger : C.text }}>🚗 ¿Llegó por un accidente?</span><div style={{ width: 38, height: 20, borderRadius: 10, background: casoForm.es_accidente ? C.danger : "rgba(255,255,255,0.1)", position: "relative" }}><div style={{ width: 16, height: 16, borderRadius: "50%", background: "#fff", position: "absolute", top: 2, left: casoForm.es_accidente ? 20 : 2, transition: "left 0.2s" }} /></div></div>{casoForm.es_accidente && (<div><div style={{ marginBottom: 14 }}><label style={{ fontSize: 11, fontWeight: 700, color: C.muted, display: "block", marginBottom: 8 }}>Tipo de caso</label><div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>{["Accidente de auto (PIP)", "Laboral", "Deportivo", "Particular"].map(o => (<button key={o} onClick={() => setCasoForm(p => ({ ...p, tipo: o }))} style={{ flex: 1, padding: "8px 6px", borderRadius: 8, border: `1px solid ${casoForm.tipo === o ? `${C.teal}50` : C.border}`, background: casoForm.tipo === o ? "rgba(45,212,191,0.15)" : "rgba(255,255,255,0.03)", color: casoForm.tipo === o ? C.teal : C.muted, fontSize: 11, fontWeight: 700, cursor: "pointer" }}>{o}</button>))}</div></div><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>{[["fecha","Fecha del accidente"],["mecanismo","¿Cómo ocurrió?"],["reporte_num","N° de reporte de choque"],["reporte_agencia","Agencia (ej: Coral Gables PD)"],["pip_aseguradora","Aseguradora del auto (PIP)"],["pip_poliza","N° de póliza PIP"],["pip_ajustador","Ajustador (nombre / contacto)"],["tercero_aseguradora","Aseguradora del otro conductor"],["abogado","Abogado (si hay)"],["lop_fecha","Fecha de la carta LOP"]].map(([k,l]) => (<Input key={k} label={l} value={casoForm[k] || ""} onChange={e => setCasoForm(p => ({ ...p, [k]: e.target.value }))} />))}</div></div>)}<div style={{ display: "flex", gap: 10, marginTop: 22, justifyContent: "flex-end" }}><Btn onClick={() => setShowCaso(false)} color={C.muted}>Cancelar</Btn><Btn onClick={guardarCaso} disabled={savingCaso} color={C.success}>{savingCaso ? "Guardando..." : "✓ Guardar caso"}</Btn></div></Modal><Modal open={showEdit} onClose={() => setShowEdit(false)} title="Editar ficha del paciente" width={620}><div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}><Input label="Nombre" value={editForm.nombre} onChange={e => setEditForm(p => ({ ...p, nombre: e.target.value }))} /><Input label="Apellido" value={editForm.apellido} onChange={e => setEditForm(p => ({ ...p, apellido: e.target.value }))} /><Input label="Edad" type="number" value={editForm.edad} onChange={e => setEditForm(p => ({ ...p, edad: e.target.value }))} /><Input label="Teléfono" value={editForm.telefono} onChange={e => setEditForm(p => ({ ...p, telefono: e.target.value }))} /><Input label="Email" value={editForm.email} onChange={e => setEditForm(p => ({ ...p, email: e.target.value }))} /><Input label="Deporte" value={editForm.deporte} onChange={e => setEditForm(p => ({ ...p, deporte: e.target.value }))} /><div style={{ gridColumn: "1/-1" }}><Input label="Condición Principal" value={editForm.condicion_principal} onChange={e => setEditForm(p => ({ ...p, condicion_principal: e.target.value }))} /></div><div style={{ gridColumn: "1/-1" }}><label style={{ fontSize: 11, fontWeight: 700, color: C.muted, display: "block", marginBottom: 8 }}>País</label><div style={{ display: "flex", gap: 8 }}>{["USA", "Colombia"].map(o => (<button key={o} onClick={() => setEditForm(p => ({ ...p, pais: o }))} style={{ flex: 1, padding: "11px 8px", borderRadius: 10, border: `1px solid ${editForm.pais === o ? `${C.teal}50` : C.border}`, background: editForm.pais === o ? "rgba(45,212,191,0.15)" : "rgba(255,255,255,0.03)", color: editForm.pais === o ? C.teal : C.muted, fontSize: 13, fontWeight: 700, cursor: "pointer" }}>{o}</button>))}</div></div></div><div style={{ display: "flex", gap: 10, marginTop: 22, justifyContent: "flex-end" }}><Btn onClick={() => setShowEdit(false)} color={C.muted}>Cancelar</Btn><Btn onClick={guardarEdit} disabled={savingEdit || !editForm.nombre} color={C.success}>{savingEdit ? "Guardando..." : "✓ Guardar cambios"}</Btn></div></Modal><Modal open={showModal} onClose={() => setShowModal(false)} title="Nueva Sesión">
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
          <div style={{ gridColumn: "1/-1" }}>
            <label style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: "uppercase", letterSpacing: 0.8, display: "block", marginBottom: 6 }}>Protocolo</label>
            <select value={form.protocolo} onChange={e => setForm(p => ({ ...p, protocolo: e.target.value }))} style={{ width: "100%", background: "rgba(255,255,255,0.05)", border: `1px solid ${C.border}`, borderRadius: 10, color: C.text, fontSize: 14, padding: "10px 14px", fontFamily: "inherit" }}>
              {["HILT", "Crioterapia", "Termografía", "Ecografía", "Acupuntura", "Rehabilitación", "Biorresonancia", "TENS", "EMS", "VALD", "InBody", "Bodygee"].map(o => <option key={o} value={o} style={{ background: "#1e293b" }}>{o}</option>)}
            </select>
          </div>
          {[{ k: "eva_pre", l: "EVA Pre (0-10)" }, { k: "eva_post", l: "EVA Post (0-10)" }, { k: "duracion_minutos", l: "Duración (min)" }].map(f => (
            <Input key={f.k} label={f.l} type="number" value={form[f.k]} onChange={e => setForm(p => ({ ...p, [f.k]: parseInt(e.target.value) || 0 }))} />
          ))}
          <div style={{ gridColumn: "1/-1" }}>
            <label style={{ fontSize: 11, fontWeight: 700, color: C.muted, textTransform: "uppercase", letterSpacing: 0.8, display: "block", marginBottom: 6 }}>Notas</label>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>{[["subjetivo","Subjetivo (S): lo que cuenta el paciente"],["objetivo","Objetivo (O): examen, hallazgos, mediciones"],["analisis","Análisis (A): tu impresión / diagnóstico"],["plan","Plan (P): tratamiento, indicaciones, próxima cita"]].map(([k,ph]) => (<textarea key={k} value={form[k]} onChange={e => setForm(p => ({ ...p, [k]: e.target.value }))} placeholder={ph} rows={2} style={{ width: "100%", background: "rgba(255,255,255,0.05)", border: `1px solid ${C.border}`, borderRadius: 10, color: C.text, fontSize: 13, padding: "10px 14px", resize: "vertical", fontFamily: "inherit", boxSizing: "border-box" }} />))}</div>
          </div>
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 22, justifyContent: "flex-end" }}>
          <Btn onClick={() => setShowModal(false)} color={C.muted}>Cancelar</Btn>
          <Btn onClick={save} disabled={saving} color={C.success}>{saving ? "Guardando..." : "✓ Registrar"}</Btn>
        </div>
      </Modal>
    </div>
  );
}

// ── PLUGIN: FLIR Camera + Galería Termográfica ─────────────
function FLIRPlugin({ patient }) {
  const { C } = useApp();
  const [tab, setTab] = useState("camara"); // camara | galeria | comparar
  const [status, setStatus] = useState("disconnected");
  const [captured, setCaptured] = useState(false);
  const [saved, setSaved] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [analisisIA, setAnalisisIA] = useState(null);
  const [imagenes, setImagenes] = useState([]);
  useEffect(() => {
    CoreServices.query("sessions", patient?.id ? { paciente_id: patient.id } : {}).then(({ data }) => {
      const termos = (data || []).filter(s => s.protocolo === "Termografía" && s.foto);
      setImagenes(termos.map((s, i) => ({ id: s.id || i, fecha: s.fecha ? new Date(s.fecha).toLocaleDateString("es-ES") : "", sesion: s.numero_sesion || (i + 1), zona: "Termografía", tsi: "Neutro", asimetria: 0, url: s.foto, notas: s.notas || "", protocolo: "Termografía" })));
    });
  }, [patient]);
  const [selectedImg, setSelectedImg] = useState(null);
  const [compareA, setCompareA] = useState(null);
  const [compareB, setCompareB] = useState(null);
  const [uploadForm, setUploadForm] = useState({ zona: "", sesion: "", tsi: "Hipertérmico", asimetria: "", notas: "", protocolo: "" });
  const canvasRef = useRef(null);
  const fileRef = useRef(null);
  const [tick, setTick] = useState(0);
  const streaming = status === "streaming";

  useEffect(() => { if (!streaming) return; const id = setInterval(() => setTick(t => t + 1), 120); return () => clearInterval(id); }, [streaming]);

  useEffect(() => {
    const c = canvasRef.current; if (!c) return;
    const ctx = c.getContext("2d"); const w = c.width, h = c.height;
    ctx.fillStyle = "#050A14"; ctx.fillRect(0, 0, w, h);
    if (status === "disconnected") return;
    const g = ctx.createRadialGradient(w * .58, h * .48, 15, w * .5, h * .5, w * .65);
    [["#ff2200", 0], ["#ff8800", .3], ["#ffaa00", .55], ["#220066", .8], ["#000033", 1]].forEach(([col, s]) => g.addColorStop(s, col));
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
    if (streaming || captured) {
      ctx.fillStyle = "rgba(255,77,77,0.35)"; ctx.beginPath(); ctx.ellipse(w * .62, h * .65, 20, 15, 0.3, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = "rgba(255,77,77,0.8)"; ctx.lineWidth = 1.5; ctx.stroke();
    }
    if (streaming) {
      const y = (tick * 10) % h; ctx.strokeStyle = "rgba(255,255,255,0.04)"; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
      ctx.fillStyle = "#fff"; ctx.font = "10px monospace"; ctx.fillText("34.2°C", w / 2 + 9, h / 2 - 5);
    }
    if (streaming || captured) { ctx.fillStyle = "#44aaff"; ctx.font = "9px monospace"; ctx.fillText("↓29.1°", 6, h - 7); ctx.fillStyle = "#ff4444"; ctx.fillText("↑37.8°", w - 42, h - 7); }
  }, [status, streaming, captured, tick]);

  async function analizarConIA(img) {
    setAnalyzing(true);
    setAnalisisIA(null);
    try {
      const systemPrompt = `Eres Alex, asistente clínico de Awake4Wellness, especialista en termografía (Dr. Javier Cuartas). Analizas el termograma en tres ejes clínicos: inflamación (zonas calientes/hipertérmicas), dolor y fatiga; y defines si el patrón corresponde a MÚSCULO (calor localizado, sobrecarga) o a NERVIO (asimetría fría en el territorio del nervio). Integra estos ejes en los campos diagnostico, inflamacion y recomendaciones. El termograma orienta; la lectura clínica final la confirma el médico. Respondes ÚNICAMENTE con JSON válido, sin markdown ni texto adicional.`;
      const userMsg = `Analiza esta imagen termográfica clínica.

DATOS:
- Paciente: ${patient?.nombre || "Paciente"} ${patient?.apellido || ""}
- Zona: ${img.zona}
- TSI: ${img.tsi}
- Asimetría: Δ${img.asimetria}°C
- Sesión: ${img.sesion} · Fecha: ${img.fecha}
- Protocolo previo: ${img.protocolo}

Devuelve este JSON:
{
  "diagnostico": "Orientación termográfica principal",
  "nivel_alarma": "L1/L2/L3",
  "inflamacion": "estado inflamatorio",
  "crioterapia": true/false,
  "hilt": true/false,
  "urgencia": "normal/moderada/alta",
  "recomendaciones": ["rec 1", "rec 2", "rec 3"],
  "progreso": "evaluación del progreso",
  "zona_anatomica": "región/estructura anatómica precisa que se ve afectada en la imagen",
  "musculos_afectados": "músculo(s) con patrón térmico alterado, o 'No concluyente'",
  "nervios_afectados": "nervio(s) o territorio neural sugerido, o 'No concluyente'"
}`;
      const contenido = img.base64 ? [{ type: "text", text: userMsg }, { type: "image_url", image_url: { url: img.base64 } }] : userMsg;
      const text = await CoreServices.askAI([{ role: "user", content: contenido }], systemPrompt);
      setAnalisisIA(JSON.parse((text || "{}").replace(/```json|```/g, "").trim()));
    } catch {
      setAnalisisIA({
        diagnostico: `Asimetría térmica Δ${img.asimetria}°C en ${img.zona} — ${img.tsi}`,
        nivel_alarma: img.asimetria >= 1.5 ? "L3" : img.asimetria >= 0.8 ? "L2" : "L1",
        inflamacion: img.tsi === "Hipertérmico" ? "Inflamación activa presente" : "Sin inflamación significativa",
        crioterapia: img.tsi === "Hipertérmico",
        hilt: img.asimetria >= 1.0,
        urgencia: img.asimetria >= 2.0 ? "alta" : "normal",
        recomendaciones: ["Continuar protocolo HILT según parámetros establecidos", "Crioterapia post-sesión indicada", "Reevaluar en próxima sesión"],
        progreso: "Evaluación basada en datos de la sesión actual",
        siguiente_sesion: `Mantener protocolo ${img.protocolo} y reevaluar con termografía en 3-4 sesiones`,
      });
    } finally { setAnalyzing(false); }
  }

  function handleUpload(e) {
    const file = e.target.files?.[0]; if (!file) return;
    const url = URL.createObjectURL(file);
    const reader = new FileReader();
    reader.onload = () => {
      const base64 = reader.result;
      const nueva = { id: Date.now(), fecha: new Date().toLocaleDateString("es-ES"), sesion: imagenes.length + 1, zona: uploadForm.zona || "Sin especificar", tsi: uploadForm.tsi, asimetria: parseFloat(uploadForm.asimetria) || 0, url, base64, notas: uploadForm.notas, protocolo: uploadForm.protocolo };
      setImagenes(prev => [nueva, ...prev]);
    };
    reader.readAsDataURL(file);
    setUploadForm({ zona: "", sesion: "", tsi: "Hipertérmico", asimetria: "", notas: "", protocolo: "" });
  }

  function guardarCaptura() {
    const nueva = { id: Date.now(), fecha: new Date().toLocaleDateString("es-ES"), sesion: imagenes.length + 1, zona: "Captura FLIR", tsi: "Hipertérmico", asimetria: 1.8, url: null, notas: "Captura en vivo FLIR One", protocolo: "Evaluación" };
    setImagenes(prev => [nueva, ...prev]);
    setSaved(true);
  }

  const tsiColor = (tsi) => tsi === "Hipertérmico" ? C.danger : tsi === "Neutro" ? C.success : C.primary;
  const asimetriaColor = (a) => a >= 1.5 ? C.danger : a >= 0.8 ? C.warning : C.success;

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
        <div>
          <h2 style={{ margin: 0, fontSize: 20, fontWeight: 800, color: C.text }}>🌡️ Termografía FLIR</h2>
          <p style={{ margin: "4px 0 0", color: C.muted, fontSize: 13 }}>{patient ? `${patient.nombre} ${patient.apellido}` : "Sin paciente"} · {imagenes.length} imágenes</p>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
