              {streaming && !captured && <><Btn onClick={() => { setCaptured(true); setStatus("connected"); }} color={C.thermo} style={{ flex: 1, maxWidth: 200, padding: "13px" }}>📸 Capturar</Btn><Btn onClick={() => setStatus("connected")} color={C.muted}>⏸ Pausar</Btn></>}
