                        <div style={{ fontSize: 12, color: C.text }}>{analisisIA.siguiente_sesion}</div>
                      </div>}
                      <button onClick={async () => {
                        let urlFoto = "";
                        if (selectedImg.base64) {
                          const resp = await fetch(selectedImg.base64);
                          const blob = await resp.blob();
