                          const sub = await CoreServices.uploadFile("Thermografias", ruta, blob);
                          if (!sub.error) urlFoto = sub.url; else alert("ERROR FOTO: " + JSON.stringify(sub.error));
                        }
                        const notas = `🌡️ Termografía — ${analisisIA.diagnostico || ""}\nZona: ${analisisIA.zona_anatomica || "-"}\nMúsculos: ${analisisIA.musculos_afectados || "-"}\nNervios: ${analisisIA.nervios_afectados || "-"}\nRecomendaciones: ${(analisisIA.recomendaciones || []).join("; ")}${urlFoto ? "\nFoto: " + urlFoto : ""}`;
                        const { error } = await CoreServices.insert("sessions", { paciente_id: patient?.id, numero_sesion: selectedImg.sesion || 1, protocolo: "Termografía", notas, foto: urlFoto || "", fecha: new Date().toISOString() });
                        alert(error ? "No se pudo guardar: " + (error.message || "error") : (urlFoto ? "Análisis y foto guardados ✓" : "Análisis guardado (la foto no se subió) ✓"));
                      }} style={{ width: "100%", padding: "12px", borderRadius: 11, background: C.successDim, border: `1px solid ${C.success}35`, color: C.success, fontSize: 13, fontWeight: 800, cursor: "pointer", marginTop: 4 }}>💾 Guardar análisis</button><button onClick={() => { const datos = { tipo: "termografia", paciente: (patient && (patient.nombre + " " + (patient.apellido || ""))) || "", fecha: new Date().toISOString(), zona: selectedImg.zona, tsi: selectedImg.tsi, asimetria: selectedImg.asimetria, sesion: selectedImg.sesion, analisis: analisisIA }; const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([JSON.stringify(datos, null, 2)], { type: "application/json" })); a.download = "termografia_" + ((patient && patient.nombre) || "paciente") + "_" + Date.now() + ".json"; a.click(); }} style={{ width: "100%", padding: "12px", borderRadius: 11, background: "rgba(56,189,248,0.12)", border: "1px solid rgba(56,189,248,0.35)", color: "#38BDF8", fontSize: 13, fontWeight: 800, cursor: "pointer", marginTop: 8 }}>📥 Descargar para Adri</button>
                    </div>
