        </div>
      )}

      {tab === "tendencia" && (
        <div>
          <Card style={{ marginBottom: 16 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: C.muted, letterSpacing: 2, marginBottom: 16 }}>NIVEL DE ESTRÉS (7 días)</div>
