// REGISTRO DE PLUGINS — agrega/quita módulos aquí
// ═══════════════════════════════════════════════════════════════
function NutriciónPlugin({ patient }) {
  const { C } = useApp();
  const [paginas, setPaginas] = useState([]);
  const [cargando, setCargando] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [progreso, setProgreso] = useState("");
  const [filas, setFilas] = useState([]);
  const [error, setError] = useState("");
  const fileRef = useRef(null);

  function cargarPdfJs() {
    return new Promise((resolve, reject) => {
      if (window.pdfjsLib) { resolve(window.pdfjsLib); return; }
      const s = document.createElement("script");
      s.src = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js";
      s.onload = () => {
        window.pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
        resolve(window.pdfjsLib);
      };
      s.onerror = () => reject(new Error("No se pudo cargar el lector de PDF"));
      document.body.appendChild(s);
    });
  }

  async function pdfAImagenes(file) {
    const pdfjsLib = await cargarPdfJs();
    const buf = await file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: buf }).promise;
    const imgs = [];
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const viewport = page.getViewport({ scale: 2 });
      const canvas = document.createElement("canvas");
      canvas.width = viewport.width;
      canvas.height = viewport.height;
      await page.render({ canvasContext: canvas.getContext("2d"), viewport }).promise;
      const base64 = canvas.toDataURL("image/jpeg", 0.85);
      imgs.push({ url: base64, base64 });
    }
    return imgs;
  }

  function imagenABase64(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        const im = new Image();
        im.onload = () => {
          const max = 1600;
          let w = im.width, h = im.height;
          if (w > max || h > max) {
            const esc = Math.min(max / w, max / h);
            w = Math.round(w * esc); h = Math.round(h * esc);
          }
          const canvas = document.createElement("canvas");
          canvas.width = w; canvas.height = h;
          canvas.getContext("2d").drawImage(im, 0, 0, w, h);
          resolve(canvas.toDataURL("image/jpeg", 0.85));
        };
        im.onerror = reject;
        im.src = reader.result;
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  function calcularEstado(rango, valor) {
    const v = parseFloat(String(valor).replace(",", "."));
    const m = String(rango).match(/(-?\d+[.,]?\d*)\s*[-–~]\s*(-?\d+[.,]?\d*)/);
    if (isNaN(v) || !m) return "";
    const min = parseFloat(m[1].replace(",", "."));
    const max = parseFloat(m[2].replace(",", "."));
    if (isNaN(min) || isNaN(max)) return "";
    return (v >= min && v <= max) ? "dentro" : "fuera";
  }

  function parsearFilas(text) {
    const limpio = (text || "").replace(/```json|```/g, "").trim();
    try {
      const d = JSON.parse(limpio);
      if (Array.isArray(d)) return d;
      if (d && Array.isArray(d.filas)) return d.filas;
    } catch (e) {}
    const filas = [];
    const re = /\{[^{}]*\}/g;
    let m;
    while ((m = re.exec(limpio)) !== null) {
      try { filas.push(JSON.parse(m[0])); } catch (e) {}
    }
    return filas;
  }

  async function handleUpload(e) {
    const file = e.target.files?.[0]; if (!file) return;
    setError(""); setFilas([]); setPaginas([]); setCargando(true);
    try {
      const esPdf = file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf");
      if (esPdf) {
        const imgs = await pdfAImagenes(file);
        setPaginas(imgs);
      } else {
        const base64 = await imagenABase64(file);
        setPaginas([{ url: base64, base64 }]);
      }
    } catch (err) {
      setError("No pude abrir el archivo: " + (err.message || err));
    } finally {
      setCargando(false);
    }
  }

  async function analizar() {
    if (!paginas.length) return;
    setAnalyzing(true); setError(""); setFilas([]); setProgreso("");
    try {
const systemPrompt = "Eres un lector de tablas. La imagen es una pagina de un reporte con una tabla de datos. Devuelve UNICAMENTE un JSON valido, sin markdown ni texto extra, con esta forma exacta: {\"filas\":[{\"sistema\":\"\",\"item\":\"\",\"rango\":\"\",\"valor\":\"\"}]}. Incluye TODAS las filas que veas en esta imagen. Para 'sistema' y 'item', escribe el texto en TRES idiomas separados por ' / ', en este orden: primero el idioma original como aparece en la imagen, luego espanol, luego frances. Ejemplo de item: 'Skin Moisture Loss / Perdida de humedad de la piel / Perte d hydratation de la peau'. Ejemplo de sistema: 'Skin / Piel / Peau'. 'rango' es el rango normal tal cual aparece, sin traducir. 'valor' es la medicion tal cual aparece, sin traducir. No agregues interpretaciones ni recomendaciones.";      const todas = [];
      for (let i = 0; i < paginas.length; i++) {
        setProgreso("Leyendo página " + (i + 1) + " de " + paginas.length + "…");
        const userMsg = "Reporte de biorresonancia" + (patient ? " del paciente " + patient.nombre + " " + (patient.apellido || "") : "") + ", página " + (i + 1) + ". Devuelve las filas de la tabla de esta imagen.";
        const contenido = [{ type: "text", text: userMsg }, { type: "image_url", image_url: { url: paginas[i].base64 } }];
        const text = await CoreServices.askAI([{ role: "user", content: contenido }], systemPrompt);
        const filasPag = parsearFilas(text);
        for (const f of filasPag) {
          todas.push({
            sistema: f.sistema || "",
            item: f.item || "",
            rango: f.rango || "",
            valor: f.valor || "",
            estado: calcularEstado(f.rango, f.valor),
          });
        }
      }
      setProgreso("");
      if (!todas.length) setError("No pude leer filas del reporte. Intenta con un PDF o foto más nítido.");
      setFilas(todas.filter((f, i, a) => a.findIndex(x => x.sistema === f.sistema && x.item === f.item && x.valor === f.valor) === i));;
    } catch (e) {
      setProgreso("");
      setError("Hubo un error al analizar: " + (e.message || e));
    } finally { setAnalyzing(false); }
  }

  const th = { textAlign: "left", padding: "10px 12px", fontSize: 11, fontWeight: 700, color: C.muted, textTransform: "uppercase", letterSpacing: 0.5, borderBottom: "1px solid " + C.border, background: "rgba(255,255,255,0.03)" };
  const td = { padding: "9px 12px", fontSize: 13, color: C.text, borderBottom: "1px solid " + C.border, verticalAlign: "top" };

  return (
    <div style={{ padding: 24, maxWidth: 820 }}>
      <h2 style={{ fontSize: 20, fontWeight: 800, color: C.text, marginTop: 0 }}>🧬 Nutrición</h2>
      <div style={{ fontSize: 12, color: C.muted, marginBottom: 16 }}>Lectura ordenada de los datos del reporte - no reemplaza análisis de laboratorio.</div>
      <div onClick={() => fileRef.current && fileRef.current.click()} style={{ background: C.surface, border: "2px dashed " + C.border, borderRadius: 16, padding: 28, textAlign: "center", marginBottom: 16, cursor: "pointer" }}>
        <input ref={fileRef} type="file" accept="image/*,application/pdf" onChange={handleUpload} style={{ display: "none" }} />
        <div style={{ fontSize: 40, marginBottom: 8 }}>📤</div>
        <div style={{ fontSize: 14, fontWeight: 700, color: C.text }}>Subir reporte (PDF o imagen)</div>
        <div style={{ fontSize: 12, color: C.muted, marginTop: 4 }}>Toca para elegir el PDF, la foto o la captura del reporte</div>
      </div>
      {cargando && <div style={{ fontSize: 13, color: C.muted, marginBottom: 16 }}>Abriendo el archivo…</div>}
      {paginas.map((p, i) => <img key={i} src={p.url} alt={"reporte " + (i + 1)} style={{ width: "100%", borderRadius: 12, border: "1px solid " + C.border, marginBottom: 8 }} />)}
      {paginas.length > 0 && <button onClick={analizar} disabled={analyzing} style={{ background: C.teal, border: "none", color: "#fff", borderRadius: 10, padding: "12px 18px", fontSize: 14, fontWeight: 700, cursor: "pointer", width: "100%", marginTop: 8, marginBottom: 16 }}>{analyzing ? (progreso || "Analizando con Alex...") : "🧠 Analizar con Alex"}</button>}
      {error && <div style={{ background: C.surface, border: "1px solid " + C.border, borderRadius: 12, padding: 16, fontSize: 13, color: C.danger, marginBottom: 16 }}>{error}</div>}
      {filas.length > 0 && (
        <div style={{ background: C.surface, border: "1px solid " + C.border, borderRadius: 12, overflow: "hidden", marginBottom: 12 }}>
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr>
                  <th style={th}>Sistema</th>
                  <th style={th}>Ítem</th>
                  <th style={th}>Rango normal</th>
                  <th style={th}>Valor</th>
                  <th style={th}>Estado</th>
                </tr>
              </thead>
              <tbody>
                {filas.map((f, i) => (
                  <tr key={i}>
                    <td style={td}>{f.sistema}</td>
                    <td style={td}>{f.item}</td>
                    <td style={td}>{f.rango}</td>
                    <td style={td}>{f.valor}</td>
                    <td style={td}>
                      {f.estado === "dentro" && <span style={{ fontSize: 11, fontWeight: 700, color: C.success, background: "rgba(16,185,129,0.12)", border: "1px solid rgba(16,185,129,0.3)", borderRadius: 20, padding: "2px 10px" }}>Dentro</span>}
                      {f.estado === "fuera" && <span style={{ fontSize: 11, fontWeight: 700, color: C.danger, background: "rgba(239,68,68,0.12)", border: "1px solid rgba(239,68,68,0.3)", borderRadius: 20, padding: "2px 10px" }}>Fuera</span>}
                      {!f.estado && <span style={{ fontSize: 12, color: C.muted }}>—</span>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
     {filas.length > 0 && <button onClick={async () => { if (!patient || !patient.id) { alert("Abre Nutrición desde un paciente para poder guardar."); return; } const cab = "Sistema | Ítem | Rango normal | Valor | Estado"; const lineas = filas.map(f => (f.sistema || "") + " | " + (f.item || "") + " | " + (f.rango || "") + " | " + (f.valor || "") + " | " + (f.estado === "dentro" ? "Dentro" : f.estado === "fuera" ? "Fuera" : "—")); const notas = cab + "\n" + lineas.join("\n"); const r = await CoreServices.insert("sessions", { paciente_id: patient.id, protocolo: "Nutrición", notas: notas, foto: "", fecha: new Date().toISOString() }); if (r.error) { alert("No se pudo guardar: " + (r.error.message || "error")); } else { alert("Guardado en la historia del paciente ✓"); } }} style={{ background: C.success, border: "none", color: "#fff", borderRadius: 10, padding: "12px 18px", fontSize: 14, fontWeight: 700, cursor: "pointer", width: "100%", marginBottom: 12 }}>💾 Guardar en la historia del paciente</button>}{filas.length > 0 && <div style={{ fontSize: 12, color: C.muted, fontStyle: "italic" }}>Esto es solo una lectura de los datos de la hoja, no un diagnóstico.</div>}
    </div>
  );
}

function CopilotoTextoAntiguo({ patient }) {
  const { C } = useApp();
  const nombrePac = patient ? `${patient.nombre || ""} ${patient.apellido || ""}`.trim() : "";
  const systemPrompt = `Eres Alex, el copiloto clínico de AWAKE4WELLNESS, la clínica del Dr. Javier Cuartas. Eres un asistente clínico profesional. Respondes en español, claro y conciso.${nombrePac ? ` Paciente actual: ${nombrePac}.` : ""}`;
  const [msgs, setMsgs] = useState([{ role: "assistant", content: `Hola, soy Alex, tu copiloto clínico${nombrePac ? ` para ${nombrePac}` : ""}. ¿En qué te ayudo?` }]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [streaming, setStreaming] = useState("");
  async function send() {
    const text = input.trim();
    if (!text || loading) return;
    setInput("");
    const next = [...msgs, { role: "user", content: text }];
    setMsgs(next); setLoading(true); setStreaming("");
    try {
      let full = "";
      await CoreServices.askAI(next.map(m => ({ role: m.role, content: m.content })), systemPrompt, chunk => { full = chunk; setStreaming(chunk); });
      setMsgs(p => [...p, { role: "assistant", content: full }]); setStreaming("");
    } catch (e) {
      setMsgs(p => [...p, { role: "assistant", content: "Error: " + e.message }]);
    } finally { setLoading(false); }
  }
  return (
    <div style={{ maxWidth: 760, margin: "0 auto" }}>
      <h2 style={{ color: C.text, fontSize: 20, marginBottom: 4 }}>🧠 ALEX — Alex</h2>
      <div style={{ color: C.muted, fontSize: 13, marginBottom: 16 }}>Asistente clínico</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 16 }}>
        {msgs.map((m, i) => (
          <div key={i} style={{ alignSelf: m.role === "user" ? "flex-end" : "flex-start", maxWidth: "85%", padding: "10px 14px", borderRadius: 12, background: m.role === "user" ? "rgba(56,189,248,0.12)" : C.surface, border: `1px solid ${C.border}`, color: C.text, fontSize: 14, lineHeight: 1.6, whiteSpace: "pre-wrap" }}>{m.content}</div>
        ))}
        {streaming && (<div style={{ alignSelf: "flex-start", maxWidth: "85%", padding: "10px 14px", borderRadius: 12, background: C.surface, border: `1px solid ${C.border}`, color: C.text, fontSize: 14, lineHeight: 1.6, whiteSpace: "pre-wrap" }}>{streaming}</div>)}
        {loading && !streaming && (<div style={{ alignSelf: "flex-start", color: C.muted, fontSize: 13 }}>Alex está escribiendo…</div>)}
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <textarea value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); } }} placeholder="Escribe tu pregunta clínica…" rows={2} style={{ flex: 1, background: C.surface, border: `1px solid ${C.border}`, borderRadius: 10, color: C.text, fontSize: 14, padding: "10px 14px", resize: "none", fontFamily: "inherit" }} />
        <button onClick={send} disabled={loading || !input.trim()} style={{ padding: "0 20px", borderRadius: 10, border: "none", background: C.teal || "#10b981", color: "#fff", fontSize: 16, cursor: loading ? "not-allowed" : "pointer" }}>{loading ? "⏳" : "↑"}</button>
      </div>
    </div>
  );
}

function CopilotoConImagenes({ patient }) {
  const { C } = useApp();
  const nombrePac = patient ? `${patient.nombre || ""} ${patient.apellido || ""}`.trim() : "";
  const systemPrompt = `Eres Alex, el copiloto clínico de AWAKE4WELLNESS, la clínica del Dr. Javier Cuartas. Eres un asistente clínico profesional. Respondes en español, claro y conciso. Si te envían una imagen clínica, descríbela y orienta de forma profesional.${nombrePac ? ` Paciente actual: ${nombrePac}.` : ""}`;
  const [msgs, setMsgs] = useState([{ role: "assistant", content: `Hola, soy Alex, tu copiloto clínico${nombrePac ? ` para ${nombrePac}` : ""}. Puedes escribirme o adjuntarme una imagen con el clip 📎. ¿En qué te ayudo?`, img: null }]);
  const [input, setInput] = useState("");
  const [img, setImg] = useState(null);
  const [loading, setLoading] = useState(false);
  const [streaming, setStreaming] = useState("");
  function handleImg(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      const image = new Image();
      image.onload = () => {
        const max = 1600; let w = image.width, h = image.height;
        if (w > max || h > max) { if (w > h) { h = Math.round(h * max / w); w = max; } else { w = Math.round(w * max / h); h = max; } }
        const canvas = document.createElement("canvas");
        canvas.width = w; canvas.height = h;
        canvas.getContext("2d").drawImage(image, 0, 0, w, h);
        setImg(canvas.toDataURL("image/jpeg", 0.85));
      };
      image.src = reader.result;
    };
    reader.readAsDataURL(file);
  }
  async function send() {
    const text = input.trim();
