function ReportePlugin({ patient }) { const { C } = useApp(); const [pdfUrl, setPdfUrl] = useState(null); const [nombre, setNombre] = useState(""); const [archivo, setArchivo] = useState(null); const [explicando, setExplicando] = useState(false); const [explicacion, setExplicacion] = useState(""); const [hablando, setHablando] = useState(false); const fileRef = useRef(null); function abrir(e) { const file = e.target.files && e.target.files[0]; if (!file) return; setNombre(file.name); setPdfUrl(URL.createObjectURL(file)); setArchivo(file); setExplicacion(""); } function cargarPdfJs() { return new Promise(function (resolve, reject) { if (window.pdfjsLib) { resolve(window.pdfjsLib); return; } const s = document.createElement("script"); s.src = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js"; s.onload = function () { window.pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js"; resolve(window.pdfjsLib); }; s.onerror = function () { reject(new Error("No se pudo cargar el lector de PDF")); }; document.body.appendChild(s); }); } async function explicar() { if (!archivo) return; setExplicando(true); setExplicacion(""); try { const pdfjsLib = await cargarPdfJs(); const buf = await archivo.arrayBuffer(); const pdf = await pdfjsLib.getDocument({ data: buf }).promise; const imgs = []; const n = Math.min(pdf.numPages, 6); for (let i = 1; i <= n; i++) { const page = await pdf.getPage(i); const viewport = page.getViewport({ scale: 1.6 }); const canvas = document.createElement("canvas"); canvas.width = viewport.width; canvas.height = viewport.height; await page.render({ canvasContext: canvas.getContext("2d"), viewport: viewport }).promise; imgs.push(canvas.toDataURL("image/jpeg", 0.8)); } const sp = "Eres Alex, el asistente clinico de Awake4Wellness (Dr. Javier Cuartas). Te paso las paginas de un reporte clinico. Explicalo en lenguaje SENCILLO y calido, en espanol, en 4 a 6 frases, como APOYO para que